UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Kaynağı belirtilmeyen bir bilgi veya görüşü aktarmak için iki eşdeğer yapı kullanılır:", "items": [{"heading": "İki Eşdeğer Yapı", "badge": "it is said / be said to", "sub_rules": [{"condition": "[[q]]It + be + said/believed/thought/reported/known + that + özne + yüklem[[/q]]:", "from": "It is believed", "to": "that the company will expand soon"}, {"condition": "[[q]]Özne + be + said/believed/thought + to + fiil[[/q]]:", "from": "The company is believed", "to": "to expand soon"}]}, {"heading": "Zaman Uyumuna Dikkat", "is_warning": true, "warning_label": "🔥 EN SIK TUZAK", "body": [{"type": "text", "text": "Ana cümledeki bildirme fiiliyle [[amber]]AYNI ANDA[[/amber]] olan bir eylem için [[q]]\"to + yalın fiil\"[[/q]] ([[b]]is believed to be[[/b]]) kullanılır."}, {"type": "text", "text": "Ana cümledeki bildirme fiilinden [[amber]]ÖNCE[[/amber]] gerçekleşmiş bir eylem için [[q]]\"to have + V3\"[[/q]] ([[b]]is believed to have been[[/b]]) kullanılır."}], "warning_text": "Bu geçmişe atıf yapısını atlamak YDS'nin sık kurduğu bir tuzaktır."}, {"heading": "İki Ek Kural", "badge": "Dikkat Edilecekler", "body": [{"type": "text", "text": "\"it\" yapısındaki [[b]]\"that\"[[/b]] [[bad]]asla atılamaz[[/bad]]."}, {"type": "text", "text": "\"to\" yapısındaki özne, \"that\" yapısındaki \"that\"tan sonraki özneyle [[dark]]AYNI[[/dark]] olmalıdır."}]}], "examples": [{"sentence": "It is believed that the ancient bridge was built over two thousand years ago.", "answer_word": "It is believed", "reasoning": "Kaynağı belirtilmeyen genel bir inanışın \"it\" yapısıyla aktarılması gerektiği için doğru cevap [[right]]\"It is believed\"[[/right]]tir; [[b]]\"that\"[[/b]] bağlacı bu yapıda asla atılamaz."}, {"sentence": "The missing hikers are believed to have been lost somewhere in the mountains for three days now.", "answer_word": "are believed to have been", "reasoning": "Kaybolma eyleminin, bildirme anından (\"şu an inanılıyor\") [[dark]]ÖNCE[[/dark]] gerçekleşmiş ve hâlâ süren bir durum olduğu için doğru cevap [[right]]\"are believed to have been\"[[/right]]dir; sadece [[wrong]]\"are believed to be\"[[/wrong]] kullanmak, kaybolmanın şu anda gerçekleştiği gibi yanlış bir zaman ilişkisi kurardı."}, {"sentence": "It is rumored that the company's CEO is planning to step down before the end of this fiscal year.", "answer_word": "It is rumored", "reasoning": "Kaynağı belirtilmeyen bir söylentinin \"it\" yapısıyla aktarılması gerektiği için doğru cevap [[right]]\"It is rumored\"[[/right]]tur; bu yapıda [[b]]\"that\"[[/b]] bağlacı kesinlikle korunmalıdır."}, {"sentence": "The ancient manuscript is believed to have been written by monks several centuries before the printing press was even invented.", "answer_word": "is believed to have been written", "reasoning": "Yazılma eyleminin, bildirme anından (\"inanılıyor\") çok [[dark]]ÖNCE[[/dark]] gerçekleşmiş ve tamamlanmış bir olay olduğu için doğru cevap [[right]]\"is believed to have been written\"[[/right]]tir; sadece [[wrong]]\"is believed to be written\"[[/wrong]] kullanmak, yazılmanın şu an gerçekleştiği gibi yanlış bir zaman ilişkisi kurardı."}]}$tagbd$::jsonb WHERE id = 'debef73d-0bf2-460e-abb8-e3fd0805d464';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Bir önceki cümledeki durumla AYNI FİKİRDE/DURUMDA olunduğunu belirtmek için, önceki cümlenin olumlu/olumsuz olmasına göre iki kalıp kullanılır:", "items": [{"heading": "so mu, neither mi?", "badge": "Olumlu / Olumsuz", "sub_rules": [{"condition": "Önceki cümle [[amber]]OLUMLU[[/amber]] ise:", "from": "so", "to": "so + yardımcı fiil + özne (\"So do I\", \"So is she\")"}, {"condition": "Önceki cümle [[amber]]OLUMSUZ[[/amber]] ise:", "from": "neither/nor", "to": "neither/nor + yardımcı fiil + özne (\"Neither do I\", \"Nor does he\")"}]}, {"heading": "Devrik Yapı ve Doğru Yardımcı Fiil", "badge": "Kurallar", "body": [{"type": "text", "text": "Bu yapılarda yardımcı fiil [[amber]]ÖZNEDEN ÖNCE[[/amber]] gelir (devrik yapı) ve kullanılan yardımcı fiil, önceki cümledeki fiile göre ([[b]]be/do/have/modal[[/b]]) seçilmelidir."}, {"type": "example_check", "correct": "So do I", "wrong_note": "\"So I do\" gibi devrik olmayan bir yapı yanlıştır"}]}, {"heading": "Anlam Çelişkisi Tuzağı", "is_warning": true, "warning_label": "⚠️ Dikkat", "body": [{"type": "text", "text": "Önceki cümle olumluyken [[bad]]\"neither\"[[/bad]] kullanmak veya olumsuzken [[bad]]\"so\"[[/bad]] kullanmak anlam açısından çelişki yaratır ve [[dark]]KESİNLİKLE YANLIŞTIR[[/dark]]."}], "warning_text": "Önceki cümlenin olumlu mu olumsuz mu olduğuna bakmadan şık seçmek bu sorularda en sık yapılan hatadır."}], "examples": [{"sentence": "Neither have I.", "answer_word": "Neither", "reasoning": "Önceki cümle (\"I've never been to Japan.\") [[dark]]OLUMSUZ[[/dark]] (\"never been\") olduğu için aynı durumu paylaşan katılma ifadesi \"neither\" ile kurulur → doğru cevap [[right]]\"Neither\"[[/right]]dır."}, {"sentence": "So can my brother.", "answer_word": "So", "reasoning": "Önceki cümle (\"My sister can speak three languages fluently.\") [[dark]]OLUMLU[[/dark]] olduğu için aynı yeteneği paylaşan katılma ifadesi \"so\" ile kurulur → doğru cevap [[right]]\"So\"[[/right]]dur; [[wrong]]\"Neither\"[[/wrong]] burada anlam çelişkisi yaratacağı için kesinlikle yanlıştır."}, {"sentence": "Neither can I.", "answer_word": "Neither", "reasoning": "Önceki cümle (\"He can't attend tomorrow's meeting...\") [[dark]]OLUMSUZ[[/dark]] bir modal (\"can't\") içerdiği için katılma ifadesi \"neither\" ile kurulur → doğru cevap [[right]]\"Neither\"[[/right]]dır; [[wrong]]\"So can I\"[[/wrong]] burada anlam çelişkisi yaratır çünkü \"so\" sadece olumlu cümlelerden sonra kullanılır."}, {"sentence": "So am I.", "answer_word": "So", "reasoning": "Önceki cümle (\"I'm absolutely exhausted...\") [[dark]]OLUMLU[[/dark]] ve yardımcı fiil olarak \"be\" fiilinin bir hali (\"am\") kullanıldığı için katılma ifadesinde de AYNI yardımcı fiil tekrarlanır → doğru cevap [[right]]\"So\"[[/right]]dur; [[wrong]]\"Neither\"[[/wrong]] kullanmak hem anlam çelişkisi yaratır hem de yanlış bir yardımcı fiil seçimine (\"do\" gibi) yol açabilirdi."}]}$tagbd$::jsonb WHERE id = '2fb1724d-fecb-4b93-a1f9-0ea8a48a9140';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Üç yapı birbirine çok benzer ama [[dark]]TAMAMEN FARKLI[[/dark]] anlamlar taşır:", "items": [{"heading": "Üç Yapı, Üç Farklı Anlam", "badge": "Fiil mi, Alışkanlık mı", "body": [{"type": "text", "text": "[[q]]\"used to\" + YALIN FİİL[[/q]] geçmişte yapılıp artık yapılmayan bir alışkanlığı anlatır ve [[dark]]SADECE geçmiş zamanda[[/dark]] kullanılır: [[b]]\"I used to smoke\"[[/b]] = eskiden sigara içerdim, artık içmiyorum."}, {"type": "text", "text": "[[q]]\"be used to\" + İSİM/-ing[[/q]] ŞU ANDA bir duruma [[amber]]ALIŞKIN OLMAYI[[/amber]] anlatır: [[b]]\"I am used to working at night\"[[/b]] = gece çalışmaya alışkınım."}, {"type": "text", "text": "[[q]]\"get used to\" + İSİM/-ing[[/q]] bir duruma [[amber]]ALIŞMA SÜRECİNİ[[/amber]] anlatır: [[b]]\"I am getting used to the new schedule\"[[/b]] = yeni programa alışıyorum."}]}, {"heading": "En Sık Tuzak: Yalın Fiil mi, -ing mi?", "is_warning": true, "warning_label": "🔥 EN SIK TUZAK", "body": [{"type": "text", "text": "[[q]]\"used to\"[[/q]] sonrası [[amber]]YALIN FİİL[[/amber]] gelirken, [[q]]\"be/get used to\"[[/q]] sonrası HER ZAMAN [[amber]]-ing veya isim[[/amber]] gelir, asla yalın fiil gelmez."}, {"type": "example_check", "correct": "I am used to working", "wrong_note": "\"I am used to work\" YANLIŞTIR"}], "warning_text": "\"used to\" ile \"be/get used to\" yapılarını karıştırıp ardından yanlış fiil formu seçmek YDS'nin en klasik tuzaklarından biridir."}], "examples": [{"sentence": "When I was a child, I used to walk to school every day, but now I take the bus.", "answer_word": "used to walk", "reasoning": "Geçmişte yapılıp artık yapılmayan bir alışkanlık anlatıldığı için doğru cevap [[right]]\"used to walk\"[[/right]]tır, [[wrong]]\"was used to walking\"[[/wrong]] değildir."}, {"sentence": "After six months in Berlin, she was used to living alone, so moving back with her parents felt strange.", "answer_word": "was used to living", "reasoning": "Burada geçmişte bir duruma [[b]]ALIŞKIN HALE GELMİŞ[[/b]] olma anlatıldığı için doğru cevap [[right]]\"was used to living\"[[/right]]tir (be used to + -ing); [[wrong]]\"used to live\"[[/wrong]] kullanmak burada \"eskiden yaşardı ama artık yaşamıyor\" gibi yanlış bir anlam katar."}, {"sentence": "It took Maria almost a year, but she eventually got used to the long commute to her new job across the city.", "answer_word": "got used to", "reasoning": "Burada zamanla bir duruma [[b]]ALIŞMA SÜRECİ[[/b]] anlatıldığı için doğru cevap [[right]]\"got used to\"[[/right]]dur (get used to + isim); [[wrong]]\"used to\"[[/wrong]] burada anlamca uymaz çünkü cümle bir sürecin SONUNDA alışmayı anlatır, geçmişte bırakılan bir alışkanlığı değil."}, {"sentence": "Twenty years ago, my father used to ride his bicycle to work every day; these days, though retired, he says he is used to waking up at 5 a.m. because of that old routine.", "answer_word": "used to ride", "reasoning": "İlk boşlukta geçmişte yapılıp artık (emekli olduğu için) yapılmayan bir alışkanlık anlatıldığından doğru cevap [[right]]\"used to ride\"[[/right]]dır; ikinci boşlukta hâlâ ŞU ANDA o saatte uyanmaya [[b]]ALIŞKIN OLMA[[/b]] durumu anlatıldığı için doğru cevap [[right]]\"is used to waking\"[[/right]]tir (be used to + -ing), [[wrong]]\"used to wake\"[[/wrong]] değildir çünkü bu alışkanlık hâlâ sürmektedir, bırakılmamıştır."}]}$tagbd$::jsonb WHERE id = '58ab2f97-23f2-4b37-b2fa-da2df95604b6';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "[[q]]\"the\"[[/q]] kullanımı KARŞILIKLI BİLİNEN/TANIMLANMIŞ bir şeye işaret eder; buna karşılık bir isim GENEL BİR KATEGORİYİ temsil ediyorsa artikel kullanılmaz:", "items": [{"heading": "\"the\": Karşılıklı Bilinen / Belirli Olan", "body": [{"type": "text", "text": "Bir isim önceki cümlede [[q]]\"a/an\"[[/q]] ile tanıtıldıysa, ikinci bahsedilişinde [[pair]]a car->the car[[/pair]] şeklinde \"the\" alır."}, {"type": "text", "text": "İsim dünyada [[dark]]TEK[[/dark]] olan bir şeyse ([[b]]\"the sun\"[[/b]], [[b]]\"the internet\"[[/b]]) ya da bir sıfat öbeği/ilgi cümleciğiyle [[amber]]BELİRLİ[[/amber]] hale getirilmişse ([[b]]\"the book ON THE TABLE\"[[/b]]) yine \"the\" kullanılır."}]}, {"heading": "Artikelsiz: Genel Kategori", "body": [{"type": "text", "text": "Bir isim [[amber]]GENEL BİR KATEGORİYİ[[/amber]] veya kavramı temsil ediyorsa (çoğul sayılabilen veya sayılamayan isimlerle) [[dark]]ARTİKEL KULLANILMAZ[[/dark]]."}, {"type": "example_check", "correct": "Books are expensive", "wrong_note": "\"The books are expensive\" BELİRLİ bir kitap grubunu anlatır, genel anlamı bozar"}]}, {"heading": "Her Zaman \"the\" İsteyen İstisnalar", "badge": "Ezberlenmesi Gereken İstisnalar", "sub_rules": [{"condition": "[[amber]]Üstünlük sıfatları[[/amber]] her zaman \"the\" ister:", "from": "best", "to": "the best"}, {"condition": "[[amber]]Sıra sayıları[[/amber]] her zaman \"the\" ister:", "from": "first", "to": "the first"}, {"condition": "[[amber]]Bazı sabit coğrafi isimler[[/amber]] (nehirler, okyanuslar) her zaman \"the\" ister:", "from": "Nile", "to": "the Nile"}]}], "examples": [{"sentence": "The information you gave me yesterday turned out to be incorrect.", "answer_word": "The", "reasoning": "\"you gave me yesterday\" ilgi cümleciği ismi [[amber]]BELİRLİ[[/amber]] hale getirdiği için doğru cevap [[right]]\"The\"[[/right]]dir (artikelsiz bırakmak yanlıştır, çünkü artık genel bir bilgi değil, belirli bir bilgiden bahsediliyor)."}, {"sentence": "Information is power in today's digital world.", "answer_word": "Information", "reasoning": "Burada genel olarak [[b]]\"bilgi\"[[/b]] kavramından (herhangi bir belirli bilgi değil) bahsedildiği için doğru cevap [[right]]artikelsiz bırakmaktır[[/right]] ([[b]]\"Information is power...\"[[/b]]), [[wrong]]\"The information\"[[/wrong]] kullanmak buradaki genel-geçer anlamı bozar."}, {"sentence": "The Pacific Ocean is the largest ocean on Earth, covering nearly a third of the planet's surface.", "answer_word": "the", "reasoning": "[[b]]\"Pacific Ocean\"[[/b]] okyanus adı sabit coğrafi isimlerden biri olduğu için her zaman [[q]]\"the\"[[/q]] alır; [[b]]\"largest\"[[/b]] ise bir [[amber]]ÜSTÜNLÜK[[/amber]] sıfatı olduğundan ikinci boşlukta da [[q]]\"the\"[[/q]] zorunludur → doğru cevap her iki boşlukta da [[right]]\"the\"[[/right]]dir."}, {"sentence": "The cars that were recalled last month had a faulty braking system, although cars in general remain one of the safest forms of transport.", "answer_word": "The", "reasoning": "İlk boşlukta [[b]]\"that were recalled last month\"[[/b]] ilgi cümleciği belirli bir araba grubunu işaret ettiği için doğru cevap [[right]]\"The\"[[/right]]dir; ikinci boşlukta [[b]]\"cars in general\"[[/b]] ifadesiyle zaten [[amber]]GENEL[[/amber]] bir kategoriden bahsedildiği açıkça belirtildiği için artikel kullanılmaz."}]}$tagbd$::jsonb WHERE id = 'f30e1a46-11df-47d9-848d-d4077d8b89f7';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Önce cümlenin [[amber]]OLUMLU[[/amber]] mu, [[amber]]OLUMSUZ/SORU[[/amber]] mu olduğuna bak:", "items": [{"heading": "Olumlu mu, Olumsuz/Soru mu?", "body": [{"type": "text", "text": "[[amber]]Olumlu[[/amber]] cümlelerde [[q]]\"some\"[[/q]] kullanılır: [[b]]\"I have some books\"[[/b]]."}, {"type": "text", "text": "[[amber]]Olumsuz ve soru[[/amber]] cümlelerinde [[q]]\"any\"[[/q]] kullanılır: [[b]]\"I don't have any books\" / \"Do you have any books?\"[[/b]]."}]}, {"heading": "İstisna: Teklif / Rica", "body": [{"type": "text", "text": "Bir şey [[amber]]teklif ederken veya rica ederken[[/amber]] soru cümlesinde bile [[q]]\"some\"[[/q]] kullanılır çünkü olumlu bir cevap beklenir."}, {"type": "example_check", "correct": "Would you like some coffee?", "wrong_note": "normal soru kuralına göre \"any\" beklenir ama teklif istisnası \"some\"u zorunlu kılar"}]}, {"heading": "\"no\" ve \"none\" Farkı", "body": [{"type": "text", "text": "[[q]]\"no\"[[/q]] doğrudan isimden önce gelir ve cümleyi [[dark]]TEK BAŞINA[[/dark]] olumsuz yapar."}, {"type": "text", "text": "[[q]]\"none\"[[/q]] ise bir isim grubunun yerine geçer ve genellikle [[pair]]none of->the/my/these[[/pair]] kalıbıyla belirli bir grubun HİÇBİRİNİ ifade eder."}]}, {"heading": "Çifte Olumsuzluk Tuzağı", "is_warning": true, "warning_label": "🔥 EN SIK TUZAK", "body": [{"type": "text", "text": "\"no\" ile birlikte ayrıca [[bad]]\"not\"[[/bad]] veya başka bir olumsuzluk sözcüğü KULLANILMAZ."}, {"type": "example_check", "correct": "I have no money / I don't have any money", "wrong_note": "\"I don't have no money\" YANLIŞTIR"}], "warning_text": "\"no\" zaten cümleyi olumsuz yaptığı için \"not\" ile birlikte kullanmak YDS'nin klasik çifte olumsuzluk tuzağıdır."}], "examples": [{"sentence": "None of the committee members objected to the new proposal during the meeting.", "answer_word": "None", "reasoning": "Boşluktan sonra [[b]]\"of the committee members\"[[/b]] (belirli bir grup + of) geldiği için doğru cevap [[right]]\"None\"[[/right]]dur; [[wrong]]\"No\"[[/wrong]] buraya gelemez çünkü \"no\" doğrudan isimden önce gelir, \"of\" ile kullanılmaz."}, {"sentence": "I didn't get any useful feedback from the reviewers.", "answer_word": "any", "reasoning": "Cümle olumsuz (\"didn't\") olduğu için doğru cevap [[right]]\"any\"[[/right]]dir; [[wrong]]\"I didn't get no useful feedback\"[[/wrong]] şeklinde hem \"didn't\" hem \"no\" kullanmak çifte olumsuzluk hatasıdır ve YDS'de her zaman yanlış şıktır."}, {"sentence": "Would you like some milk in your coffee, or do you prefer it black?", "answer_word": "some", "reasoning": "Bu bir [[amber]]TEKLİF[[/amber]] cümlesidir ve olumlu bir cevap beklenir, bu yüzden soru cümlesi olmasına rağmen doğru cevap [[right]]\"some\"[[/right]]dur; normal soru kuralına göre [[wrong]]\"any\"[[/wrong]] beklenirdi ama teklif/rica istisnası burada \"some\"u zorunlu kılar."}, {"sentence": "There is no scientific evidence to support the claim that the supplement improves memory.", "answer_word": "no", "reasoning": "Cümlede \"not\" ya da başka bir olumsuzluk sözcüğü yok, ama isimden ([[b]]\"scientific evidence\"[[/b]]) hemen önce gelen kelime cümleyi TEK BAŞINA olumsuz yapacak → doğru cevap [[right]]\"no\"[[/right]]dur; [[wrong]]\"any\"[[/wrong]] burada yanlıştır çünkü cümle zaten olumlu bir yapıdadır (\"is\") ve \"any\" tek başına cümleyi olumsuz yapamaz, mutlaka ayrı bir olumsuzluk sözcüğüyle birlikte kullanılır."}]}$tagbd$::jsonb WHERE id = '846bf314-b2e6-450d-be30-25797767de11';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Boşluktan hemen sonraki kelimeye bak: çıplak bir sıfat/zarf geliyorsa [[q]]\"so\"[[/q]], bir isim öbeği geliyorsa [[q]]\"such\"[[/q]] kullanılır:", "items": [{"heading": "Boşluktan Sonraki Kelimeye Bak", "badge": "so vs such Testi", "sub_rules": [{"condition": "Çıplak bir [[amber]]sıfat/zarf[[/amber]] geliyorsa:", "from": "so", "to": "so exhausting that"}, {"condition": "Bir [[amber]]isim öbeği[[/amber]] (a/an+sıfat+isim ya da sadece isim) geliyorsa:", "from": "such", "to": "such an exhausting day that"}, {"condition": "[[amber]]many/much/few/little[[/amber]] + çoğul/sayılamayan isim geliyorsa (istisna):", "from": "so", "to": "so many people that"}]}, {"heading": "Ortak Zorunluluk: \"that\" Cümleciği", "body": [{"type": "text", "text": "Her iki yapı da [[q]]\"that\"[[/q]] ile devam eden tam bir sonuç cümleciği gerektirir — \"that\" düşerse yapı sadece [[b]]so/such[[/b]] vurgusu olur, sonuç anlamı taşımaz."}]}], "examples": [{"sentence": "The lecture was so boring that half the students fell asleep.", "answer_word": "so", "reasoning": "Boşluktan sonra çıplak bir sıfat ([[b]]\"boring\"[[/b]]) var, araya isim girmiyor → doğru cevap [[right]]\"so\"[[/right]]dur; [[wrong]]\"such\"[[/wrong]] burada yanlıştır çünkü ardından bir isim öbeği gelmiyor."}, {"sentence": "It was such a persuasive speech that the whole audience stood up and applauded.", "answer_word": "such", "reasoning": "Boşluktan sonra isim öbeği ([[b]]\"a persuasive speech\"[[/b]]) geldiği için doğru cevap [[right]]\"such\"[[/right]]tur; [[wrong]]\"so\"[[/wrong]] seçilseydi cümlenin \"so persuasive a speech that\" şeklinde (sıfat isimden önce, a/an'den sonra) yeniden kurulması gerekirdi — sade \"so a persuasive speech\" yanlıştır."}, {"sentence": "There was so much noise coming from the construction site that the teacher had to close the classroom windows.", "answer_word": "so", "reasoning": "Boşluktan sonra miktar belirteci [[b]]\"much\"[[/b]] ve sayılamayan bir isim ([[b]]\"noise\"[[/b]]) geldiği için doğru cevap yine [[right]]\"so\"[[/right]]dur (many/much/few/little istisnası); [[wrong]]\"such\"[[/wrong]] burada kullanılamaz çünkü \"such much\" diye bir yapı İngilizce'de yoktur."}, {"sentence": "It was such a disaster that the government had to declare a state of emergency.", "answer_word": "such a", "reasoning": "Boşluktan sonra sıfatsız, çıplak bir isim ([[b]]\"disaster\"[[/b]]) geldiği için doğru cevap [[right]]\"such a\"[[/right]]dır; [[wrong]]\"so\"[[/wrong]] burada yanlıştır çünkü \"so\" bir isim öbeğinden önce tek başına kullanılamaz, mutlaka bir sıfat veya zarfı doğrudan nitelemelidir."}]}$tagbd$::jsonb WHERE id = 'cdd5c4d4-6508-47c2-9e66-36252f23d6e9';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Bir isim [[amber]]-s[[/amber]] ile bitse bile ya da çoğul GÖRÜNSE bile, asıl TÜRÜNE bakmak gerekir:", "items": [{"heading": "İsmin Türüne Bak, Görünüşüne Değil", "badge": "Sayılamayan vs Sadece-Çoğul", "sub_rules": [{"condition": "[[amber]]Sayılamayan isimler[[/amber]] (news, information, advice, furniture, equipment) her zaman tekil fiil alır:", "from": "the news", "to": "is"}, {"condition": "[[amber]]Sadece çoğul formda bulunan isimler[[/amber]] (clothes, trousers, scissors, glasses, jeans, people) her zaman çoğul fiil alır:", "from": "people", "to": "are"}]}, {"heading": "Toplu İsimler: Bütün mü, Üyeler mi?", "body": [{"type": "text", "text": "Toplu isimler ([[b]]team, family, government, committee[[/b]]) bir [[amber]]BÜTÜN[[/amber]] olarak düşünülürse tekil, üyelerinin [[amber]]AYRI AYRI[[/amber]] davrandığı vurgulanırsa çoğul fiil alabilir."}, {"type": "example_check", "correct": "The team is playing well", "wrong_note": "\"The team are arguing among themselves\" üyelerin ayrı ayrı davrandığını vurgular"}]}, {"heading": "Özne ile Fiil Arasına Giren İfadeler", "body": [{"type": "text", "text": "[[q]]\"as well as\"[[/q]], [[q]]\"together with\"[[/q]], [[q]]\"along with\"[[/q]] gibi ifadeler ÖZNEYİ ÇOĞULLAŞTIRMAZ — fiil hâlâ asıl özneye göre çekimlenir."}]}], "examples": [{"sentence": "The information the journalist gathered seems quite reliable.", "answer_word": "seems", "reasoning": "\"information\" sayılamayan bir isimdir, çoğul görünmese de her zaman tekil fiil alır → doğru cevap [[right]]\"seems\"[[/right]]tir."}, {"sentence": "The manager, together with his three assistants, is responsible for the final decision.", "answer_word": "is", "reasoning": "\"together with his three assistants\" özneyi çoğullaştırmaz, asıl özne tekil olan [[b]]\"the manager\"[[/b]]dır → doğru cevap [[right]]\"is\"[[/right]]dir, [[wrong]]\"are\"[[/wrong]] burada yaygın bir tuzaktır."}, {"sentence": "Her brand-new trousers are unfortunately a size too small, so she had to exchange them.", "answer_word": "are", "reasoning": "\"trousers\" SADECE ÇOĞUL formda bulunan bir isimdir ve her zaman çoğul fiil alır → doğru cevap [[right]]\"are\"[[/right]]dir, tekil [[wrong]]\"is\"[[/wrong]] asla kullanılmaz."}, {"sentence": "The jury are deeply divided, with some members pushing for a guilty verdict and others for acquittal.", "answer_word": "are", "reasoning": "\"with some members... others...\" ifadesi üyelerin AYRI AYRI davrandığını vurguluyor → doğru cevap [[right]]\"are\"[[/right]]dir; bütün olarak hareket eden bir jüriden bahsedilseydi ([[b]]\"the jury is deliberating\"[[/b]]), tekil fiil doğru olurdu."}]}$tagbd$::jsonb WHERE id = '80b5c1aa-ce11-45f6-8040-c04aae11221f';
UPDATE public.exam_tactics SET breakdown = $tagbd${"intro": "Bazı fiillerden sonra [[q]]-ing[[/q]] mi yoksa [[q]]to-infinitive[[/q]] mi geldiği cümlenin anlamını [[dark]]TAMAMEN[[/dark]] değiştirir:", "items": [{"heading": "remember / stop / try: Anlam Değiştiren -ing vs to-infinitive", "is_warning": true, "warning_label": "🔥 ANLAM TUZAĞI", "body": [{"type": "text", "text": "Bu fiilleri gördüğünde otomatik bir kural uygulamak yerine her seferinde cümlenin ANLAMINA bakılmalıdır."}], "meaning_pairs": [[{"word": "remember + -ing", "meaning": "geçmişte yapılan bir eylemi hatırlamak (\"I remember locking the door\")"}, {"word": "remember + to-infinitive", "meaning": "yapılması gereken görevi unutmamak (\"I remembered to lock the door\")", "variant": "wrong"}], [{"word": "stop + -ing", "meaning": "bir eylemi durdurmak/bırakmak (\"He stopped smoking\")"}, {"word": "stop + to-infinitive", "meaning": "başka bir eylemi yapmak için durmak (\"He stopped to smoke\")", "variant": "wrong"}], [{"word": "try + -ing", "meaning": "bir şeyi deneme/test etme (\"Try restarting the computer\")"}, {"word": "try + to-infinitive", "meaning": "bir şeyi başarmaya çalışma/çaba (\"I tried to open the door\")", "variant": "wrong"}]], "warning_text": "Cümlenin anlamına bakmadan bu fiillerden sonra otomatik olarak -ing ya da to-infinitive seçmek, YDS'de neredeyse her zaman yanlış şıkkı seçtirir."}, {"heading": "Nasıl Ayırt Edilir?", "body": [{"type": "text", "text": "Fiili gördüğünde otomatik bir kural uygulamak yerine cümlenin [[amber]]ANLAMINA[[/amber]] bakılmalı: eylem zaten gerçekleşmiş mi (geçmişe dönük), yoksa henüz gerçekleşmemiş bir amaç/görev mi anlatılıyor?"}]}], "examples": [{"sentence": "On his way to the office, he stopped to buy a coffee.", "answer_word": "stopped to buy", "reasoning": "Yolda durup kahve ALMAK bir [[amber]]AMAÇ[[/amber]] belirttiği için doğru cevap [[right]]\"stopped to buy\"[[/right]]dır; [[wrong]]\"stopped buying\"[[/wrong]] kullanılsaydı anlam \"kahve almayı bırakmak/kesmek\" gibi tamamen farklı bir şeye dönüşürdü."}, {"sentence": "I'll never forget that day — I clearly remember seeing him at the airport.", "answer_word": "remember seeing", "reasoning": "Geçmişte yaşanmış bir anıyı HATIRLAMA anlatıldığı için doğru cevap [[right]]\"remember seeing\"[[/right]]dir; [[wrong]]\"remember to see\"[[/wrong]] kullanılsaydı bu, henüz gerçekleşmemiş, yapılması gereken bir görevi unutmama anlamına gelirdi ki bu da \"that day\"i hatırlamakla çelişirdi."}, {"sentence": "The teacher suggested that the students try solving the problem using a different method before giving up.", "answer_word": "try solving", "reasoning": "Burada farklı bir YÖNTEMİ DENEME/TEST ETME anlamı olduğu için doğru cevap [[right]]\"try solving\"[[/right]]dir (-ing); [[wrong]]\"try to solve\"[[/wrong]] kullanılsaydı anlam 'çözmeye çalışmak, başarmaya uğraşmak' olur ki bu da cümledeki 'farklı bir yöntem dene' önerisiyle tam örtüşmez."}, {"sentence": "He finally stopped arguing with his neighbor after years of conflict.", "answer_word": "stopped arguing", "reasoning": "Yıllar süren bir eylemin SONA ERDİRİLMESİ anlatıldığı için doğru cevap [[right]]\"stopped arguing\"[[/right]]dir (-ing, bir eylemi bırakmak); [[wrong]]\"stopped to argue\"[[/wrong]] kullanılsaydı anlam 'tartışmak için durdu' gibi tuhaf bir amaç cümlesine dönüşürdü, metnin bağlamıyla çelişirdi."}]}$tagbd$::jsonb WHERE id = '33a90a12-792a-4987-8ef9-fe6d0ebf1b0e';
